def propose_evidence_groups(text, spans, public_hypothesis_key, ordinary_candidate_indices):
    def span_text(x):
        if isinstance(x, str):
            return x
        if isinstance(x, dict):
            for k in ('literal_original_text', 'text', 'content'):
                v = x.get(k)
                if isinstance(v, str):
                    return v
            a = x.get('start')
            b = x.get('end')
            if isinstance(text, str) and isinstance(a, int) and isinstance(b, int):
                return text[a:b]
        if isinstance(x, (list, tuple)):
            best = ''
            for v in x:
                if isinstance(v, str) and len(v) > len(best):
                    best = v
            if best:
                return best
            if len(x) >= 2 and isinstance(text, str) and isinstance(x[0], int) and isinstance(x[1], int):
                return text[x[0]:x[1]]
        return ''
    xs = list(spans)
    ts = [span_text(x).casefold() for x in xs]
    ids = []
    for p, x in enumerate(xs):
        v = x.get('original_span_index') if isinstance(x, dict) else None
        ids.append(v if isinstance(v, int) else p)
    out = []
    seen = set()
    def has(i, terms):
        return 0 <= i < len(ts) and any(term in ts[i] for term in terms)
    def add(pos):
        g = sorted(set(ids[i] for i in pos if 0 <= i < len(ids)))
        z = tuple(g)
        if len(g) >= 2 and z not in seen:
            seen.add(z)
            out.append(g)
    def before(i, terms, width):
        for j in reversed(range(max(0, i - width), i)):
            if has(j, terms):
                return j
        return -1
    key = public_hypothesis_key
    if key in ('nda-12', 'nda-13'):
        target = ('independently develop', 'independent development', 'independently discover', 'without use of', 'without reference to') if key == 'nda-12' else ('third party', 'third-party', 'third person', 'another source', 'source other than', 'outside source')
        intro = ('does not include', 'shall not include', 'shall not apply', 'does not apply', 'foregoing shall not apply', 'exceptions', 'except information', 'excludes')
        for i in range(len(ts)):
            if has(i, target):
                j = before(i, intro, 7)
                if j >= 0:
                    add((j, i))
    elif key in ('nda-1', 'nda-2', 'nda-3'):
        if key == 'nda-3':
            marks = ('oral', 'orally', 'verbally', 'spoken', 'communicated visually')
        elif key == 'nda-1':
            marks = ('marked confidential', 'designated as', 'identified as', 'identify it as', 'confidential legend', 'made aware')
        else:
            marks = ('technical', 'technology', 'engineering', 'software', 'business', 'financial', 'commercial', 'marketing', 'personnel', 'customer')
        leads = ('confidential information means', 'confidential information shall mean', 'proprietary information means', 'with respect to all', 'all information disclosed', 'confidential information disclosed', 'confidential information means:')
        tails = ('reduce', 'reduced to writing', 'confirm', 'confirmed', 'within ', 'marked', 'identify', 'transmit')
        for i in range(len(ts)):
            if has(i, marks):
                q = [i]
                j = before(i, leads, 4)
                if j >= 0:
                    q.append(j)
                    for k in range(j + 1, i):
                        if has(k, marks + ('writing', 'written', 'tangible', 'including')):
                            q.append(k)
                if key in ('nda-1', 'nda-3'):
                    for k in range(i + 1, min(len(ts), i + 3)):
                        if has(k, tails):
                            q.append(k)
                add(q)
    elif key in ('nda-5', 'nda-7'):
        people = ('employee', 'consultant', 'contractor', 'advisor', 'adviser', 'agent', 'affiliate', 'representative')
        force = ('shall not disclose', 'may disclose', 'may be disclosed', 'authorizes', 'limit access', 'disclose confidential', 'disclose evaluation', 'access to confidential')
        definitions = ('representatives shall include', 'representatives” shall include', 'representatives shall mean')
        for i in range(len(ts)):
            if has(i, people) and has(i, ('disclos', 'access', 'need to know', 'receive')):
                q = [i]
                j = before(i, force, 5)
                if j >= 0:
                    q.append(j)
                d = before(i, definitions, 9)
                if d >= 0:
                    q.append(d)
                for k in range(max(0, i - 2), i):
                    if len(ts[k].strip()) < 35 or ts[k].rstrip().endswith(('except:', 'its', 'and')):
                        q.append(k)
                add(q)
    elif key == 'nda-8':
        compel = ('required by law', 'required to disclose', 'legally compelled', 'subpoena', 'court order', 'legal process', 'governmental authority')
        notice = ('notify', 'notice to', 'written notice', 'advised of the requirement')
        for i in range(len(ts)):
            if has(i, notice):
                j = before(i, compel, 9)
                if j >= 0:
                    add((j, i))
    elif key in ('nda-16', 'nda-20'):
        ending = ('termination', 'expiration', 'conclusion', 'end of the', 'decides that it does not wish', 'completion of the project', 'discussions conclude')
        command = ('return', 'destroy', 'delete all', 'deliver to', 'cease use', 'no copies will be', 'not retain')
        retain = ('retain one', 'archival', 'archive', 'backup', 'recordkeeping', 'legal counsel', 'required by law')
        for i in range(len(ts)):
            if has(i, command):
                q = [i]
                j = before(i, ending, 4)
                if j >= 0:
                    q.append(j)
                for k in range(max(0, i - 2), min(len(ts), i + 3)):
                    if k != i and has(k, command):
                        q.append(k)
                if key == 'nda-20':
                    for k in range(max(0, i - 5), min(len(ts), i + 6)):
                        if has(k, retain):
                            q.append(k)
                if i + 1 < len(ts) and len(ts[i + 1].strip()) < 18:
                    q.append(i + 1)
                add(q)
    elif key == 'nda-15':
        strong = ('no rights in', 'no right, title', 'no title, license', 'no license', 'grants no rights', 'shall remain the sole property', 'does not grant', 'not acquire any intellectual property')
        q = [i for i in range(len(ts)) if has(i, strong)]
        add(q)
    elif key == 'nda-19':
        strong = ('shall survive', 'survive termination', 'continue to be bound', 'continue in force', 'remain subject to this agreement', 'will continue to be bound')
        q = [i for i in range(len(ts)) if has(i, strong)]
        add(q)
        for i in q:
            if has(i, ('period which is either', 'period which is', 'either ')):
                add(range(i, min(len(ts), i + 5)))
    elif key == 'nda-4':
        strong = ('solely for the purpose', 'only for the purpose', 'for no other purpose', 'not use the confidential', 'use the same exclusively', 'shall not use', 'used only for')
        q = [i for i in range(len(ts)) if has(i, strong)]
        add(q)
    elif key == 'nda-10':
        facts = ('discussions or negotiations', 'agreement has been', 'fact that', 'announcement or disclosure of the project', 'terms, conditions or other facts')
        lead = ('will not disclose', 'shall not disclose', 'confidential information subject', 'without the prior written consent')
        for i in range(len(ts)):
            if has(i, facts):
                j = before(i, lead, 4)
                if j >= 0:
                    add((j, i))
    elif key == 'nda-17':
        copy = ('copy', 'copies', 'reproduction', 'duplicate')
        condition = ('only the necessary', 'without permission', 'solely for the purpose', 'retain one', 'shall contain', 'not retain')
        for i in range(len(ts)):
            if has(i, copy):
                q = [i]
                for k in range(max(0, i - 2), min(len(ts), i + 3)):
                    if k != i and has(k, condition):
                        q.append(k)
                add(q)
    elif key == 'nda-18':
        strong = ('solicit the employment', 'solicit any', 'employ or engage', 'contact any other employee', 'induce any employee')
        q = [i for i in range(len(ts)) if has(i, strong)]
        add(q)
    return out
